settings.markdownTextFunction:
 if (data.length) {
    const attributes = ['Address', 'Email', 'HOD', 'Phone'];
    let info = {
        entityName: data[0].entityName || 'Not found',
        fields: {}
    };

    attributes.forEach(key => {
        info.fields[key] = data[0][key] || 'Not found';
    });

    const allMissing = Object.values(info.fields).every(v => v === 'Not found');

    if (allMissing) {
        return `<div class="no-data-card"><h1 class="card-title">Information on ${info.entityName}</h1>
                <div class="no-data-block"><div class="no-data-content">
                <p class="no-data-title">No building information available</p></div></div></div>`;
    }

    const icons = { Address: 'place', Email: 'mail_outline', HOD: 'person', Phone: 'call', };
    const labels = { Address: 'Address', Email: 'Email', HOD: 'HOD', Phone: 'Phone Number' };

    let html = `<div class="card"><h1 class="card-title">Information on ${info.entityName}</h1><div class="attributes">`;

    attributes.forEach(key => {
        html += `<div class="attribute_container">
                 <div class="icon_wrapper"><tb-icon class="icon" color="primary" matButtonIcon>${icons[key]}</tb-icon></div>
                 <div class="attribute_content"><p class="attribute">${info.fields[key]}</p>
                 <span class="attribute_label">${labels[key]}</span></div></div>`;
    });

    return html + '</div></div>';
}

