settings.cellContentFunction:
var html = '<div style="display:flex;flex-direction:row;flex-wrap:wrap;gap:5px;margin:6px 0;align-items:center">';

if (entity.current_A != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">Curr: ' +
        Number(entity.current_A).toFixed(2) + ' A</div>';
}

if (entity.voltage_V != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">Volt: ' +
        Number(entity.voltage_V).toFixed(1) + ' V</div>';
}

if (entity.power_mean != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">PM: ' +
        Number(entity.power_mean).toFixed(2) + '</div>';
}

if (entity.accel_resultant_rms != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">Vib: ' +
        Number(entity.accel_resultant_rms).toFixed(3) + '</div>';
}

if (entity.battery_current_mA != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">Bat Cur: ' +
        Number(entity.battery_current_mA).toFixed(1) + ' mA</div>';
}

if (entity.battery_voltage_V != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">Bat Volt: ' +
        Number(entity.battery_voltage_V).toFixed(2) + ' V</div>';
}

if (entity.pressure_mean != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">Pr M: ' +
        Number(entity.pressure_mean).toFixed(2) + ' kPa</div>';
}

if (entity.temperature_C != null) {
    html += '<div style="padding:2px 8px;background:#e0e0e0;border-radius:16px;">Temp: ' +
        Number(entity.temperature_C).toFixed(1) + ' °C</div>';
}

html += '</div>';

return html;

rowClick.customFunction:
const $injector = widgetContext.$injector;
const deviceService = $injector.get(widgetContext.servicesMap.get('deviceService'));

deviceService.getDevice(entityId.id).subscribe(device => {
    if (device.type === 'infusion-pump') {
        openDashboardState('infusion_pump');
    } else if (device.type === 'oxygen-concentrator') {
        openDashboardState('oxygen_concentrator');
    } else if (device.type === 'patient-monitor') {
        openDashboardState('patient_monitor');
    } else {
        openDashboardState('suction_machine');
    }
});

function openDashboardState(stateId) {
    const params = {
        entityId: entityId,
        entityName: entityName
    };
    widgetContext.stateController.openState(stateId, params, false);
}

