settings.cardCss:
.card {
    width: 100%;
    height: 100%;
    border: 2px solid #ccc;
    box-sizing: border-box;
}

.card .content {
    padding: 20px;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-around;
    height: 100%;
    box-sizing: border-box;
}

.card .content .column {
    display: flex;
    flex-direction: column;    
    /* Changed from space-around to space-between so elements push to top and bottom */
    justify-content: space-between; 
    /* Ensures the column takes up the full inner height to span top-to-bottom */
    height: 100%; 
}

.card h1 {
    text-transform: uppercase;
    color: #999;
    font-size: 20px;
    font-weight: bold;
    margin: 0;
    padding-bottom: 10px;
    line-height: 32px;
}

.card .value {
    font-size: 30px;
    font-weight: 100;
    /* Center-aligns the value horizontally within the column */
    align-self: center; 
    /* Optional: removes default margins if any interfere with exact bottom positioning */
    margin: 0; 
}

.card .description {
    font-size: 20px;
    color: #999;
}

