valueColor.colorFunction:
var monitoringStatus = value;

if (typeof monitoringStatus !== 'undefined' && monitoringStatus !== null) {
  if (monitoringStatus === 'INACTIVE') {
    return 'red';
  } else if (monitoringStatus === 'ACTIVE') {
    return 'green';
  }
}

// Default fallback color if status is unknown or undefined
return 'gray';

